-- ── hand-written: what may happen to a bill ─────────────────────────────────────────────────────
-- The guard of a bill, whoever writes the row, the function below included. A bill starts as a
-- draft; once posted it is never changed, and only a draft is removed. The times on a row are
-- the database's own. Only a session signed in as postgres itself (a migration, or the removal
-- of a synthetic test company) is not held to this.
CREATE FUNCTION app.check_supplier_bill() RETURNS trigger
  LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
BEGIN
  IF session_user = 'postgres' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN
    IF OLD.tenant_id IS DISTINCT FROM app.tenant_id() THEN
      RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'a posted bill is never removed' USING ERRCODE = 'SE225';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM app.tenant_id() THEN
    RAISE EXCEPTION 'not a member of this company' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT isfinite(NEW.bill_date) OR NOT isfinite(coalesce(NEW.due_date, NEW.bill_date)) THEN
    RAISE EXCEPTION 'a date on a bill is a day on the calendar' USING ERRCODE = 'SE233';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' THEN
      RAISE EXCEPTION 'a bill starts as a draft' USING ERRCODE = 'SE224';
    END IF;
    NEW.created_at := now();
    NEW.updated_at := clock_timestamp();
  ELSE
    IF OLD.status <> 'draft' THEN
      RAISE EXCEPTION 'a posted bill is never changed' USING ERRCODE = 'SE225';
    END IF;
    IF NEW.id <> OLD.id OR NEW.tenant_id <> OLD.tenant_id OR NEW.created_by <> OLD.created_by OR NEW.created_at <> OLD.created_at THEN
      RAISE EXCEPTION 'what a bill is and who wrote it never change' USING ERRCODE = 'SE225';
    END IF;
    -- Always later than what anyone read before this change, so a screen opened earlier can tell.
    NEW.updated_at := clock_timestamp();
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION app.check_supplier_bill() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER supplier_bills_check
  BEFORE INSERT OR UPDATE OR DELETE ON public.supplier_bills
  FOR EACH ROW EXECUTE FUNCTION app.check_supplier_bill();
--> statement-breakpoint
ALTER TABLE public.supplier_bills ENABLE ALWAYS TRIGGER supplier_bills_check;
