-- The journal of a bill stands with the posted bill that names it. It is never reversed: it has
-- no function for a reversal, so one is refused.
CREATE FUNCTION app.journal_backed_supplier_bill(p_journal public.journals) RETURNS boolean
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT EXISTS (
      SELECT 1 FROM public.supplier_bills b
      WHERE b.tenant_id = p_journal.tenant_id AND b.id = p_journal.source_id AND b.journal_id = p_journal.id AND b.status = 'posted'
        AND b.number = p_journal.document_number AND b.bill_date = p_journal.journal_date)
  $$;
